import math
import numpy as np

def akar_semua(f, a, b, n=1000):
    xs = np.linspace(a, b, n + 1)
    hasil = set()
    for i in range(n + 1):
        x0 = float(xs[i])
        f0 = f(x0)
        if f0 == 0:
            hasil.add(round(x0, 3) + 0.0)
            continue
        if i == n:
            break
        x1 = float(xs[i + 1])
        f1 = f(x1)
        if f0 * f1 < 0:
            lo, hi = x0, x1
            while hi - lo > 1e-9:
                m = (lo + hi) / 2
                if f(lo) * f(m) <= 0:
                    hi = m
                else:
                    lo = m
            hasil.add(round((lo + hi) / 2, 3) + 0.0)
    return sorted(hasil)

